import { useState } from 'react';

function Header({ user, onLogin, cartCount, onCartClick }) {
  const [email, setEmail] = useState('');

  function submitLogin(event) {
    event.preventDefault();
    if (email.trim()) onLogin(email.trim());
  }

  return (
    <header className="header">
      <div className="brand">Simple Store</div>
      <div className="header-actions">
        {user ? <span className="user">Hi, {user}</span> : (
          <form className="login-form" onSubmit={submitLogin}>
            <input value={email} onChange={(event) => setEmail(event.target.value)} placeholder="Admin email" type="email" required />
            <button type="submit">Login</button>
          </form>
        )}
        <button className="cart-button" onClick={onCartClick}>Cart ({cartCount})</button>
      </div>
    </header>
  );
}

export default Header;
